# -*- coding: utf-8 -*-
"""Tema 40 — Kakuranger Merah. Source of truth alert HTML/CSS."""
from pathlib import Path
BASE = Path(__file__).parent
RAW = "https://raw.githubusercontent.com/MasAjie12/kakuranger-red-alert-assets/refs/heads/main/"
BG = RAW + "bg.png"
SAKURA = RAW + "sakura.png"
LEFT = RAW + "hiasan.png"
RIGHT = RAW + "hiasan-kanan.png"
LIMIT = 5120
CSS = r'''html,body{margin:0;background:transparent;overflow:hidden}.kr40-card{box-sizing:border-box;position:relative;display:flex;align-items:center;justify-content:center;width:680px;max-width:96%;height:278px;margin:0 auto;border:3px solid #d8aa45;border-radius:24px;overflow:hidden;isolation:isolate;font-family:'Trebuchet MS','Segoe UI',sans-serif;color:#fff;text-align:center;background:#1b090b;box-shadow:0 14px 38px rgba(18,2,5,.78),0 0 28px rgba(220,39,45,.3);animation:kr40-in .72s cubic-bezier(.2,.9,.3,1.08) both,kr40-breathe 5.6s ease-in-out 1s infinite}.kr40-bg,.kr40-sakura{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;pointer-events:none}.kr40-bg{z-index:0;object-position:center;filter:saturate(1.08) contrast(1.04) brightness(.62);animation:kr40-zoom 17s ease-in-out infinite alternate}.kr40-sakura{z-index:1;opacity:.24;mix-blend-mode:screen;object-position:center;filter:saturate(1.18) brightness(.84);animation:kr40-sakura 15s ease-in-out infinite alternate}.kr40-veil{position:absolute;z-index:2;top:0;left:0;right:0;bottom:0;background:linear-gradient(180deg,rgba(20,3,7,.14),rgba(20,3,7,.68)),linear-gradient(90deg,rgba(20,3,7,.72),transparent 34%,transparent 66%,rgba(20,3,7,.72));pointer-events:none}.kr40-hiasan{position:absolute;z-index:5;top:50%;width:112px;height:154px;object-fit:contain;pointer-events:none;filter:drop-shadow(0 5px 10px rgba(220,39,45,.65));animation:kr40-float 4.8s ease-in-out infinite}.kr40-left{left:12px;transform:translateY(-50%)}.kr40-right{right:12px;transform:translateY(-50%);animation-delay:.42s}.kr40-body{position:relative;z-index:6;width:100%;height:100%;padding:27px 132px 31px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0}.kr40-kicker{color:#f6d58a;font-size:14px;font-weight:900;letter-spacing:4px;text-transform:uppercase;text-shadow:0 2px 7px #190205;animation:kr40-rise .55s .08s both}.kr40-amount{max-width:100%;color:#fff5df;font-size:43px;font-weight:900;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 3px 0 #7f151b,0 0 18px #e12c36,0 0 28px rgba(245,190,70,.72);animation:kr40-pop .68s .12s both,kr40-pulse 2.6s ease-in-out 1s infinite}.kr40-tag{margin-top:7px;color:#f4c76d;font-size:13px;font-weight:900;letter-spacing:1.7px;text-transform:uppercase;text-shadow:0 2px 7px #190205}.kr40-who{max-width:100%;margin-top:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#fff;font-size:24px;font-weight:900;text-shadow:0 2px 8px #190205,0 0 12px #190205}.kr40-msg{max-width:100%;margin-top:8px;color:#ffe9de;font-size:17px;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-shadow:0 2px 8px #190205}.kr40-mark{position:absolute;z-index:7;right:18px;bottom:14px;width:33px;height:33px;display:flex;align-items:center;justify-content:center;color:#f6d58a;font-size:19px;font-weight:900;background:rgba(103,10,18,.9);border:2px solid #d8aa45;border-radius:50%;box-shadow:0 4px 10px rgba(0,0,0,.55);animation:kr40-mark .6s .5s cubic-bezier(.2,.9,.3,1.2) both}.kr40-frame{position:absolute;z-index:7;top:9px;left:9px;right:9px;bottom:9px;border:1px solid rgba(216,170,69,.5);border-radius:16px;pointer-events:none}.kr40-shine{position:absolute;z-index:8;top:0;left:0;width:28%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,240,210,.18),transparent);pointer-events:none;animation:kr40-shine 4.6s linear infinite}@keyframes kr40-in{from{opacity:0;transform:translateY(24px) scale(.93)}to{opacity:1;transform:none}}@keyframes kr40-breathe{50%{box-shadow:0 17px 42px rgba(18,2,5,.85),0 0 42px rgba(220,39,45,.48)}}@keyframes kr40-zoom{to{transform:scale(1.08)}}@keyframes kr40-sakura{to{transform:scale(1.06) translateX(1.5%)}}@keyframes kr40-rise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:none}}@keyframes kr40-pop{from{opacity:0;transform:scale(.65)}to{opacity:1;transform:scale(1)}}@keyframes kr40-pulse{50%{transform:scale(1.045)}}@keyframes kr40-float{0%,100%{filter:drop-shadow(0 5px 10px rgba(220,39,45,.55))}50%{filter:drop-shadow(0 10px 16px rgba(245,190,70,.78)) brightness(1.08)}}@keyframes kr40-mark{from{opacity:0;transform:rotate(-35deg) scale(.3)}to{opacity:1;transform:rotate(-8deg) scale(1)}}@keyframes kr40-shine{from{transform:translateX(-150%)}to{transform:translateX(430%)}}@media(max-width:560px){.kr40-card{height:246px}.kr40-body{padding-left:92px;padding-right:92px}.kr40-hiasan{width:82px;height:126px}.kr40-left{left:2px}.kr40-right{right:2px}.kr40-amount{font-size:34px}.kr40-who{font-size:20px}.kr40-msg{font-size:14px}}@media(prefers-reduced-motion:reduce){.kr40-card,.kr40-bg,.kr40-sakura,.kr40-hiasan,.kr40-amount,.kr40-shine,.kr40-mark{animation:none!important}}'''

def build(platform, token, tag):
    return (f'<!-- KAKURANGER MERAH ALERT — {platform} --><div class="kr40-card">'
            f'<img class="kr40-bg" src="{BG}" alt=""><img class="kr40-sakura" src="{SAKURA}" alt=""><div class="kr40-veil"></div>'
            f'<img class="kr40-hiasan kr40-left" src="{LEFT}" alt=""><img class="kr40-hiasan kr40-right" src="{RIGHT}" alt=""><div class="kr40-body">'
            '<div class="kr40-kicker">KAKURANGER RED</div><div class="kr40-amount">{amount}</div>' + tag +
            f'<div class="kr40-who">{token}</div><div class="kr40-msg">{{message}}</div></div><div class="kr40-mark">忍</div><div class="kr40-frame"></div><div class="kr40-shine"></div></div>')

for slug, token, tag in (("sociabuzz", "{supporter}", '<div class="kr40-tag">{from_text}</div>'), ("saweria", "{donator}", "")):
    html = build(slug.title(), token, tag)
    assert "{amount}" in html and "{message}" in html and "\n" not in html and 'style="' not in html
    (BASE / f"{slug}-alert.html").write_text(html, encoding="utf-8")
    (BASE / f"{slug}-alert.css").write_text(CSS, encoding="utf-8")
assert CSS.count("{") == CSS.count("}") and len(CSS.encode()) <= LIMIT
print("OK alert", len(CSS.encode()), "bytes CSS")
